CREATE TABLE IF NOT EXISTS dealerships(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,position_json JSON NULL,spawn_json JSON NULL);
CREATE TABLE IF NOT EXISTS dealership_stock(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,dealership_id BIGINT UNSIGNED NOT NULL,model VARCHAR(100) NOT NULL,price BIGINT UNSIGNED NOT NULL,stock INT NOT NULL DEFAULT 0,class VARCHAR(32) NULL,metadata_json JSON NULL,INDEX(dealership_id),FOREIGN KEY(dealership_id) REFERENCES dealerships(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS dmv_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,character_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,action VARCHAR(32) NOT NULL,value VARCHAR(100) NULL,cost BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(character_id,created_at),FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE,FOREIGN KEY(vehicle_id) REFERENCES character_vehicles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS impound_vehicles(vehicle_id BIGINT UNSIGNED PRIMARY KEY,reason VARCHAR(255) NULL,fine BIGINT UNSIGNED NOT NULL DEFAULT 0,impounded_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vehicle_id) REFERENCES character_vehicles(id) ON DELETE CASCADE);
